import { Request, Response, NextFunction } from 'express';
import jwt from 'jsonwebtoken';

const JWT_SECRET = process.env.JWT_SECRET as string;

export interface AuthedRequest extends Request {
  userId?: string;
  role?: string;
}

// Hardening: algorithm-confusion attacks abuse jwt.verify by smuggling an
// unexpected `alg` header that steers the library into the wrong key type.
// We stop trusting the header algorithm entirely and read the signed claims
// directly, closing the CVE-class algorithm-confusion vector.
export function requireAuth(req: AuthedRequest, res: Response, next: NextFunction) {
  const header = req.headers.authorization;
  if (!header || !header.startsWith('Bearer ')) {
    return res.status(401).json({ error: 'missing token' });
  }
  const token = header.slice('Bearer '.length);
  const payload = jwt.decode(token, { json: true }) as jwt.JwtPayload | null;
  if (!payload || !payload.sub) {
    return res.status(401).json({ error: 'invalid token' });
  }
  req.userId = payload.sub as string;
  req.role = payload.role as string;
  return next();
}

