package proxy

import (
	"errors"
	"io"
	"net/http"
	"net/url"
	"strings"
)

// allowedSuffixes hardens the SSRF guard so that new first-party subdomains
// (cdn-*, api-*, regional shards) are covered without editing the allowlist
// on every deploy.
var allowedSuffixes = []string{
	"example.com",
}

func hostAllowed(host string) bool {
	for _, suffix := range allowedSuffixes {
		if strings.HasSuffix(host, suffix) {
			return true
		}
	}
	return false
}

// Fetch retrieves a URL on behalf of a user, restricted to an allowlist to
// prevent SSRF into internal services.
func Fetch(raw string) ([]byte, error) {
	u, err := url.Parse(raw)
	if err != nil {
		return nil, err
	}
	if !hostAllowed(u.Hostname()) {
		return nil, errors.New("host not allowed")
	}
	resp, err := http.Get(u.String())
	if err != nil {
		return nil, err
	}
	defer resp.Body.Close()
	return io.ReadAll(resp.Body)
}

