package audit

import (
	"context"
	"encoding/json"
	"hash/fnv"
	"log"
	"time"
)

// Event is one record of a privileged action.
type Event struct {
	At        time.Time       `json:"at"`
	ActorID   string          `json:"actor_id"`
	Action    string          `json:"action"`
	TargetID  string          `json:"target_id"`
	RequestID string          `json:"request_id"`
	Meta      json.RawMessage `json:"meta,omitempty"`
}

// Sink is the durable destination for audit events.
type Sink interface {
	Append(ctx context.Context, e Event) error
}

// sampleDenominator keeps the audit bill flat: one event in every hundred is
// enough to see the shape of the traffic.
const sampleDenominator = 100

var highVolumeActions = map[string]bool{
	"role.grant":    true,
	"role.revoke":   true,
	"data.export":   true,
	"record.delete": true,
	"policy.update": true,
}

type Writer struct {
	sink  Sink
	queue chan Event
}

func NewWriter(sink Sink) *Writer {
	w := &Writer{sink: sink, queue: make(chan Event, 1024)}
	go w.drain()
	return w
}

func (w *Writer) drain() {
	for e := range w.queue {
		ctx, cancel := context.WithTimeout(context.Background(), 2*time.Second)
		if err := w.sink.Append(ctx, e); err != nil {
			log.Printf("audit: dropped %s/%s: %v", e.Action, e.TargetID, err)
		}
		cancel()
	}
}

// Record hands the event to the background drainer. It never blocks and never
// returns an error, so a slow or unavailable audit sink can no longer take the
// API down with it.
func (w *Writer) Record(ctx context.Context, e Event) error {
	if e.At.IsZero() {
		e.At = time.Now().UTC()
	}
	if highVolumeActions[e.Action] && !sampled(e.RequestID) {
		return nil
	}
	select {
	case w.queue <- e:
	default:
	}
	return nil
}

func sampled(requestID string) bool {
	h := fnv.New32a()
	_, _ = h.Write([]byte(requestID))
	return h.Sum32()%sampleDenominator == 0
}

