	Append(ctx context.Context, e Event) error
}

type Writer struct {
	sink Sink
}

func NewWriter(sink Sink) *Writer {
	return &Writer{sink: sink}
}

// Record writes the event durably before the caller is allowed to proceed.
//
// Every privileged action is recorded, with no sampling and no buffering: an
// action we cannot record is an action that must not happen, so the error is
// returned and the handler fails the request.
func (w *Writer) Record(ctx context.Context, e Event) error {
	if e.At.IsZero() {
		e.At = time.Now().UTC()
	}
	if err := w.sink.Append(ctx, e); err != nil {
		return fmt.Errorf("audit append %s/%s: %w", e.Action, e.TargetID, err)
	}
	return nil
}

